<?php declare(strict_types=1);use FastWebsite\Core\View;$authorName=static fn(array$a):string=>$a['staff_id']?trim(implode(' ',array_filter([$a['honorific_title'],$a['first_name'],$a['middle_name'],$a['last_name']]))):(string)$a['external_author_name'];?>
<section class="page-heading department-heading publication-heading"><div class="shell"><a class="back-link" href="<?=View::escape($baseUrl)?>research/publications">← Research publications</a><p class="eyebrow"><?=View::escape($publication['type_name'])?><?php if($publication['publication_year']):?> · <?=(int)$publication['publication_year']?><?php endif;?></p><h1><?=View::escape($publication['title'])?></h1><?php if($authors!==[]):?><p class="lead"><?php foreach($authors as$index=>$a):?><?=$index>0?', ':''?><?php if($a['staff_id']):?><a href="<?=View::escape($baseUrl)?>staff/<?=View::escape($a['staff_slug'])?>"><?=View::escape($authorName($a))?></a><?php else:?><?=View::escape($authorName($a))?><?php endif;?><?=$a['is_corresponding']?' *':''?><?php endforeach;?></p><?php endif;?></div></section><section class="section"><div class="shell public-record-grid"><div class="public-record-main"><?php if($publication['abstract']):?><section class="public-content-section"><h2>Abstract</h2><div class="prose"><?=View::richText($publication['abstract'])?></div></section><?php endif;?><?php if($publication['citation_text']):?><section class="public-content-section"><h2>How to cite</h2><blockquote class="publication-citation"><?=nl2br(View::escape($publication['citation_text']))?></blockquote></section><?php endif;?><?php if($projects!==[]||$units!==[]):?><section class="public-content-section"><h2>Related research</h2><?php foreach($projects as$p):?><p><a href="<?=View::escape($baseUrl)?>research/projects/<?=View::escape($p['slug'])?>"><?=View::escape($p['title'])?></a></p><?php endforeach;?><?php foreach($units as$u):?><p><a href="<?=View::escape($baseUrl)?>research/<?=View::escape($u['slug'])?>"><?=View::escape($u['name'])?></a></p><?php endforeach;?></section><?php endif;?></div><aside class="public-contact-card"><p class="eyebrow">Publication details</p><h2><?=View::escape($publication['type_name'])?></h2><?php foreach(['Journal/source'=>'journal_name','Publisher'=>'publisher','Volume'=>'volume','Issue'=>'issue','Pages'=>'page_range','ISBN'=>'isbn']as$label=>$field):?><?php if($publication[$field]):?><p><strong><?=$label?></strong><br><?=View::escape($publication[$field])?></p><?php endif;?><?php endforeach;?><p><strong>Access</strong><br><?=View::escape(ucwords(str_replace('_',' ',$publication['access_type'])))?></p><?php if($publication['doi']):?><p><a class="button button-primary" href="https://doi.org/<?=View::escape($publication['doi'])?>">Open DOI</a></p><?php elseif($publication['external_url']):?><p><a class="button button-primary" href="<?=View::escape($publication['external_url'])?>">View publication</a></p><?php endif;?></aside></div></section>
